import * as THREE from 'three';
// A real depth-tested billboard. Pointer hit testing uses its 3D geometry.
export function createWorldInteraction(scene,camera,canvas){
 const textureCanvas=document.createElement('canvas');textureCanvas.width=384;textureCanvas.height=112;const context=textureCanvas.getContext('2d'),texture=new THREE.CanvasTexture(textureCanvas);texture.magFilter=texture.minFilter=THREE.NearestFilter;texture.generateMipmaps=false;texture.colorSpace=THREE.SRGBColorSpace;
 const material=new THREE.MeshBasicMaterial({map:texture,transparent:true,depthWrite:false,side:THREE.DoubleSide}),mesh=new THREE.Mesh(new THREE.PlaneGeometry(1.65,.48),material);mesh.name='3D interaction button';mesh.visible=false;scene.add(mesh);const ray=new THREE.Raycaster(),ndc=new THREE.Vector2();let action=null,label='',hover=false,drawnHover=false;
 function draw(){context.clearRect(0,0,384,112);context.fillStyle='#101e2b';context.fillRect(6,8,378,104);context.fillStyle=hover?'#a9e3b7':'#658c96';context.fillRect(0,0,376,104);context.fillStyle=hover?'#345848':'#152c3c';context.fillRect(6,6,364,92);context.fillStyle=hover?'#d4f4bb':'#9de4ca';context.fillRect(12,12,352,4);context.font='30px DotGothic16,monospace';context.textAlign='center';context.textBaseline='middle';context.fillText(label,188,55);context.fillStyle='#adc9c7';context.font='15px DotGothic16,monospace';context.fillText('タップ / クリック / E',188,85);texture.needsUpdate=true;drawnHover=hover;}
 document.fonts?.ready.then(()=>{if(label)draw();});
 function hit(event){if(!mesh.visible)return false;const rect=canvas.getBoundingClientRect();if(document.pointerLockElement===canvas)ndc.set(0,0);else ndc.set((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(ndc,camera);return ray.intersectObject(mesh,false).length>0;}
 function update(candidate,allowed=true){if(!candidate||!allowed){mesh.visible=false;action=null;canvas.style.cursor='';return;}const nextLabel=candidate.label||'開く';mesh.visible=true;action=candidate.action;mesh.position.copy(candidate.position);mesh.quaternion.copy(camera.quaternion);const distance=camera.position.distanceTo(mesh.position);mesh.scale.setScalar(THREE.MathUtils.clamp(distance/4,.72,1.15));mesh.updateMatrixWorld();if(label!==nextLabel||hover!==drawnHover){label=nextLabel;draw();}}
 function pointer(event){if(!hit(event))return false;event.preventDefault();const invoke=action;mesh.visible=false;action=null;invoke?.();return true;}
 canvas.addEventListener('pointermove',event=>{hover=hit(event);if(hover!==drawnHover&&mesh.visible)draw();canvas.style.cursor=hover?'pointer':'';});
 return {update,pointer,hide(){mesh.visible=false;action=null;},key(event){if(!mesh.visible||event.code!=='KeyE'||event.repeat||/INPUT|SELECT|TEXTAREA/.test(event.target.tagName))return false;event.preventDefault();const invoke=action;mesh.visible=false;action=null;invoke?.();return true;}};
}
